@startuml

class Ingredient {
  + Name
  + MeasuringUnit
  + QuantityInStock
}

class Dish {
  + ID
  + Name
}

class IngredientDish {
  + Quantity
}

class Table {
  + ID
  + MaximumAmountOfPeople
}

class Meal {
  + Date
  + StartTime
  + EndTime
}

class DishMeal {
  + Times_Served
}

class Person {
  + Name
  + Address
}

class Client extends Person {
  + TaxIdentificationNumber
}

class Waiter extends Person {
  + ID
  + PhoneNumber
}

Ingredient "1" -- "*" IngredientDish
IngredientDish "*" -- "1" Dish
Dish "1" -- "*" DishMeal
DishMeal "*" -- "1" Meal
Meal "*" -- "1" Table
Meal "*" -- "0..1" Client
Meal "*" -- "1" Waiter

@enduml

